import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { useUser } from '../session/useSession';
import { claimsKey, type Claim, type ClaimStatus } from './useClaims';

const ACTIONS: Array<{ action: string; status: ClaimStatus; label: string }> = [
  { action: 'open', status: 'OPEN', label: 'Open' },
  { action: 'settle', status: 'SETTLED', label: 'Settle' },
  { action: 'void', status: 'VOID', label: 'Void' },
];

// A claim's number and status, and the buttons that open, settle or void it. A change its status does not
// allow, or a settle by the user who opened the claim, is refused by the server, and the refusal shows on the claim until its next action.
function ClaimStatusCell({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: Claim }) {
  const [user] = useUser();
  const queryClient = useQueryClient();
  const change = useMutation({
    mutationFn: (status: ClaimStatus) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status`, { status, by: user ?? '' }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  return (
    <>
      <span data-testid="claim-number">{claim.number ?? ''}</span>{' '}
      <span data-testid="claim-status">{claim.status}</span>{' '}
      <span data-testid="claim-opened-by">{claim.openedBy ?? ''}</span>{' '}
      {ACTIONS.map((a) => (
        <button
          key={a.action}
          type="button"
          data-testid={`claim-${a.action}`}
          disabled={change.isPending}
          onClick={() => change.mutate(a.status)}
        >
          {a.label}
        </button>
      ))}{' '}
      {change.isError && (
        <span data-testid="claim-error" role="alert">
          {change.error.message}
        </span>
      )}
    </>
  );
}

export const contribution = ClaimCells.fill({ order: 20, Component: ClaimStatusCell });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

/**
 * Runs a form's mutation, ignoring a second submit while the first has not answered (a double
 * click), so one submit stores one record. The guard is a ref, set synchronously, because a
 * second click can land before `isPending` has re-rendered the button disabled.
 */
export function useSubmitOnce<V>(mutation: UseMutationResult<unknown, Error, V, unknown>) {
  const inFlight = useRef(false);
  return (vars: V) => {
    if (inFlight.current) return;
    inFlight.current = true;
    mutation
      .mutateAsync(vars)
      .catch(() => {
        // the refusal is shown from the mutation's own error state
      })
      .finally(() => {
        inFlight.current = false;
      });
  };
}
